CREATE TABLE t0(id INTEGER PRIMARY KEY, c0 ANY, c1 ANY DEFAULT 'd', c2 INTEGER UNIQUE, c3 ANY UNIQUE) STRICT;
CREATE TABLE t1(id INTEGER PRIMARY KEY, c0 VARCHAR(10), c1  CHECK(c1 IS NULL OR length(c1) < 40), c2 TEXT CHECK(c2 IS NULL OR length(c2) < 40), c3);
INSERT OR IGNORE INTO t1(c0, c1, c2, c3) VALUES(NULL, NULL, 4.5e-310, 895);
INSERT OR IGNORE INTO t1(c0, c1, c2, c3) VALUES(NULL, 'gamma', -388, -935);
INSERT OR IGNORE INTO t1(c0, c1, c2, c3) VALUES(x'159e57eec6', -92.27, 818.723, NULL);
INSERT OR IGNORE INTO t1(c0, c1, c2, c3) VALUES('alpha', 707, x'', -2.5);
CREATE TABLE t2(id INTEGER PRIMARY KEY, c0 REAL, c1 REAL DEFAULT 'd', c2 INTEGER, c3 VARCHAR(10) CHECK(c3 IS NULL OR length(c3) < 40), ref INTEGER REFERENCES t1(id));
INSERT OR IGNORE INTO t2(c0, c1, c2, c3, ref) VALUES(NULL, 875, 2.5, x'52c7e3f1fe1f', NULL);
SELECT length('sigma'), upper('sigma'), lower('sigma'), substr('sigma', 3, 5), instr('sigma', ' pad '), replace('sigma', '', ''), trim('sigma'), ltrim('sigma', 'ab'), hex('sigma'), quote('sigma'), unicode('sigma'), 'sigma' LIKE '%é%', 'sigma' GLOB '*', char(87, 708), 'sigma' || ' pad ', 'sigma' < ' pad ', 'sigma' = ' pad ' COLLATE NOCASE;
SELECT length('-7'), upper('-7'), lower('-7'), substr('-7', 1, 3), instr('-7', 'eta'), replace('-7', 'a', ''), trim('-7'), ltrim('-7', 'ab'), hex('-7'), quote('-7'), unicode('-7'), '-7' LIKE '%', '-7' GLOB 'a*', char(66, 346), '-7' || 'eta', '-7' < 'eta', '-7' = 'eta' COLLATE NOCASE;
SELECT length('zeta'), upper('zeta'), lower('zeta'), substr('zeta', 2, 2), instr('zeta', 'kappa'), replace('zeta', '', '_'), trim('zeta'), ltrim('zeta', 'ab'), hex('zeta'), quote('zeta'), unicode('zeta'), 'zeta' LIKE 'a%', 'zeta' GLOB '*[a-m]*', char(74, 211), 'zeta' || 'kappa', 'zeta' < 'kappa', 'zeta' = 'kappa' COLLATE NOCASE;
WITH RECURSIVE f(n, a, b) AS (SELECT 1, 0, 1 UNION ALL SELECT n + 1, b, a + b FROM f WHERE n < 41) SELECT n, a FROM f ORDER BY n DESC LIMIT 5;
WITH RECURSIVE s(x) AS (SELECT 9 UNION ALL SELECT CASE WHEN x % 2 THEN 3 * x + 1 ELSE x / 2 END FROM s WHERE x <> 1) SELECT count(*), max(x), group_concat(x) FROM s;
WITH a(x) AS (VALUES(1),(2),(3)), b(y) AS (SELECT x * x FROM a) SELECT x, y FROM a, b ORDER BY x, y;
